import{_ as t,c as o,o as a,ah as n,ao as p,ap as s}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"彩虹桥的那一端——神与一切活物所立的约","description":"「彩虹桥」的说法很美，而圣经里的彩虹更美：那是神与一切活物所立永远的约。","frontmatter":{"title":"彩虹桥的那一端——神与一切活物所立的约","description":"「彩虹桥」的说法很美，而圣经里的彩虹更美：那是神与一切活物所立永远的约。"},"headers":[],"relativePath":"zh/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"zh/pets-in-heaven/rainbow-bridge-covenant.md"}'),i={name:"zh/pets-in-heaven/rainbow-bridge-covenant.md"};function r(l,e,h,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>「大家都说它走过彩虹桥了。可是，这只是好听的话，还是真的有盼望？」</p><p class="pl-quote-soft">有意思的是，圣经里真的有彩虹——而且那约，是为动物立的。</p></div><section class="pl-section"><h2>一、那一道彩虹，是为动物立的</h2><p>洪水之后，神与挪亚立约，说祂不再用洪水毁灭全地。但祂立约的对象，不只是挪亚和他的子孙：</p><blockquote><p><strong>创世记 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>请留意「<em>every living creature</em>」——神把飞鸟、牲畜、地上一切的走兽，都列进了立约的对象。祂甚至把彩虹放在云中，作为<strong>与大地、与一切活物</strong>的记号。</p><p>在整本圣经里，这是一个极少被注意、却极其温柔的事实：<strong>神曾经正式地、永远地，与动物立约。</strong></p><p>所以在人的想象里有了「彩虹桥」这个名字，其实并不那么离题。那道光，圣经说就是一个记号——记号的意义从来不是「结束」，而是「还有下文」。</p></section><section class="pl-section"><h2>二、在将来的世界里，它们可以安然躺卧</h2><p>先知以赛亚描述神要造的新世界时，画面的主角之一是动物：</p><blockquote><p><strong>以赛亚书 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>启示录则让我们听见，在那个最后的敬拜里，有谁在唱歌：</p><blockquote><p><strong>启示录 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>「一切受造之物」都在敬拜。不是只有人。</p><p>而诗篇用一句最短的话总结了这件事：</p><blockquote><p><strong>诗篇 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>凡有气息的——包括它——都在那首歌里面。</p></section><section class="pl-section"><h2>三、所以彩虹桥的那一端，是神的应许</h2><p>我们不能替神多做应许，但我们可以停留在祂已经说的话里：祂与一切活物立了约；祂要造的世界里有动物和平共存；祂最后的敬拜里有「一切受造之物」；凡有气息的都要赞美祂。</p><p>这些经文没有说「你的它一定在那里」。但它们让一句话变得完全可以祷告：「主啊，愿祢的应许里有它。」而祂是那位连彩虹都愿意为动物留下的神。</p><p class="pl-quote-soft">想一想：如果神愿意为动物留下彩虹，祂怎么会不记得它？</p></section><div class="pl-quote"><p>「祢曾把彩虹放在云中，作为与一切活物所立的记号。<br>今天我看见那道光的时候，我会想起它。<br>愿它在祢的应许里得平安，如同祢所应许的。<br>也愿我在想念它的日子里，被祢的约托住。阿们。」</p></div><section class="pl-section"><h2>给你的一个小仪式</h2><p>下雨后若有彩虹出现，那可以是你们的记号。站在那里几秒钟，对它说话——不必有结论，不必说得完整。那道光在圣经里本来就是「约的记号」，而记号的意思是：神没有忘记。</p><p><a href="/zh/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 下一篇：<a href="/zh/pets-in-heaven/permission-to-grieve">允许自己悲伤</a></p></section><div class="pl-cta"><h2>留下一起看过的风景。</h2><p>把它的照片做成纪念卡片、海报或一段影片，让那些一起走过的日子，有一个可以保存的样子。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下载</a></div><div class="pl-bible"><h3>让圣经的话继续陪你</h3><p>文中引用的经文都出自圣经。用《彩虹圣经》随时阅读神的话、设置每日经文小组件，在想念它的日子里仍有一盏灯。</p><div class="pl-bible-shots"><figure><img src="'+p+'" alt="Rainbow Bible 圣经小组件显示 2 Timothy 2:13" loading="lazy"><figcaption>每日经文放在主屏幕</figcaption></figure><figure><img src="'+s+'" alt="Rainbow Bible App 的「天堂里的毛孩」主题，显示 Matthew 10:29-31" loading="lazy"><figcaption>切换到「天堂里的毛孩」主题读经</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 获取《彩虹圣经》</a></div>',8)])])}const v=t(i,[["render",r]]);export{g as __pageData,v as default};
